package fibheap

import (
	"fmt"
	"sync"
)

// Example of using the thread-safe Fibonacci heap
func ExampleThreadSafeUsage() {
	heap := NewFloatFibHeap()

	// Use wait group to coordinate goroutines
	var wg sync.WaitGroup

	// Start multiple goroutines that will concurrently access the heap
	for i := 0; i < 10; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()

			// Each goroutine adds some elements
			for j := 0; j < 100; j++ {
				heap.Enqueue(float64(id*100 + j))
			}

			// Each goroutine tries to remove some elements
			for j := 0; j < 50; j++ {
				heap.DequeueMin()
			}
		}(i)
	}

	// Wait for all goroutines to finish
	wg.Wait()

	fmt.Printf("Final heap size: %d\n", heap.Size())
	// Output: Final heap size: 500
}
EOF
```

